import React, { useState, useEffect, useRef } from 'react';
import API_URLS, { BRAND, CATEGORIES } from './config';

function App() {
  const [soundscapes, setSoundscapes] = useState([]);
  const [filteredSoundscapes, setFilteredSoundscapes] = useState([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');
  const [showForm, setShowForm] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [loading, setLoading] = useState(true);
  const [playingId, setPlayingId] = useState(null);
  const [formData, setFormData] = useState({
    id: '', title: '', category: '', duration: '', tags: '',
    uploaderId: 'user-demo', blobUrl: ''
  });

  const audioRef = useRef(null);

  // ============ FETCH SOUNDSCAPES ============
  const fetchSoundscapes = async () => {
    try {
      setLoading(true);
      const res = await fetch(API_URLS.getAll);
      const data = await res.json();
      setSoundscapes(data || []);
    } catch (err) {
      console.error('Fetch error:', err);
      setSoundscapes([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchSoundscapes(); }, []);

  // ============ SEARCH + FILTER ============
  useEffect(() => {
    let result = [...soundscapes];
    if (activeCategory !== 'All') {
      result = result.filter(s => s.category === activeCategory);
    }
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      result = result.filter(s =>
        s.title?.toLowerCase().includes(q) ||
        s.category?.toLowerCase().includes(q) ||
        s.tags?.some(t => t.toLowerCase().includes(q))
      );
    }
    setFilteredSoundscapes(result);
  }, [soundscapes, searchQuery, activeCategory]);

  // ============ CREATE ============
  const handleCreate = async (e) => {
    e.preventDefault();
    try {
      const newItem = {
        id: 'sc-' + Date.now(),
        title: formData.title,
        category: formData.category,
        duration: parseInt(formData.duration),
        tags: formData.tags.split(',').map(t => t.trim()).filter(Boolean),
        uploaderId: formData.uploaderId,
        uploadDate: new Date().toISOString(),
        playCount: 0,
        blobUrl: formData.blobUrl
      };
      await fetch(API_URLS.create, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newItem)
      });
      if (window.appInsights) {
        window.appInsights.trackEvent({ name: 'SoundscapeCreated', properties: { category: newItem.category }});
      }
      fetchSoundscapes();
      resetForm();
    } catch (err) { console.error('Create error:', err); }
  };

  // ============ UPDATE (with .replace fix) ============
  const handleUpdate = async (e) => {
    e.preventDefault();
    try {
      const updated = {
        id: formData.id,
        title: formData.title,
        category: formData.category,
        duration: parseInt(formData.duration),
        tags: formData.tags.split(',').map(t => t.trim()).filter(Boolean),
        uploaderId: formData.uploaderId,
        blobUrl: formData.blobUrl
      };
      const url = API_URLS.update.replace('{id}', formData.id);
      await fetch(url, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updated)
      });
      if (window.appInsights) {
        window.appInsights.trackEvent({ name: 'SoundscapeUpdated', properties: { id: formData.id }});
      }
      fetchSoundscapes();
      resetForm();
    } catch (err) { console.error('Update error:', err); }
  };

  // ============ DELETE (with .replace fix) ============
  const handleDelete = async (id) => {
    if (!window.confirm('Delete this soundscape?')) return;
    try {
      const url = API_URLS.delete.replace('{id}', id);
      await fetch(url, { method: 'DELETE' });
      if (window.appInsights) {
        window.appInsights.trackEvent({ name: 'SoundscapeDeleted', properties: { id }});
      }
      fetchSoundscapes();
    } catch (err) { console.error('Delete error:', err); }
  };

  // ============ EDIT MODE ============
  const handleEdit = (sc) => {
    setFormData({
      id: sc.id, title: sc.title, category: sc.category,
      duration: sc.duration.toString(),
      tags: sc.tags?.join(', ') || '',
      uploaderId: sc.uploaderId, blobUrl: sc.blobUrl
    });
    setEditMode(true);
    setShowForm(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const resetForm = () => {
    setFormData({ id: '', title: '', category: '', duration: '', tags: '', uploaderId: 'user-demo', blobUrl: '' });
    setEditMode(false);
    setShowForm(false);
  };

  // ============ AUDIO PLAYBACK ============
  const handlePlay = (sc) => {
    if (playingId === sc.id) {
      audioRef.current?.pause();
      setPlayingId(null);
    } else {
      if (audioRef.current) {
        audioRef.current.src = sc.blobUrl;
        audioRef.current.play().catch(err => console.log('Audio play blocked:', err));
        setPlayingId(sc.id);
        if (window.appInsights) {
          window.appInsights.trackEvent({ name: 'SoundscapePlayed', properties: { id: sc.id, title: sc.title }});
        }
      }
    }
  };

  // ============ STATS ============
  const totalPlays = soundscapes.reduce((sum, s) => sum + (s.playCount || 0), 0);
  const totalDuration = soundscapes.reduce((sum, s) => sum + (s.duration || 0), 0);

  return (
    <div style={S.app}>
      {/* Animated background orbs */}
      <div style={S.orb1}></div>
      <div style={S.orb2}></div>
      <div style={S.orb3}></div>

      {/* HEADER */}
      <header style={S.header}>
        <div style={S.logoRow}>
          <svg width="48" height="48" viewBox="0 0 48 48">
            <defs>
              <linearGradient id="logoGrad" x1="0" y1="0" x2="48" y2="48">
                <stop offset="0%" stopColor={BRAND.teal} />
                <stop offset="50%" stopColor={BRAND.azure} />
                <stop offset="100%" stopColor={BRAND.violet} />
              </linearGradient>
            </defs>
            <circle cx="24" cy="24" r="3" fill="url(#logoGrad)" />
            <circle cx="24" cy="24" r="9" fill="none" stroke="url(#logoGrad)" strokeWidth="2" opacity="0.8" />
            <circle cx="24" cy="24" r="15" fill="none" stroke="url(#logoGrad)" strokeWidth="1.5" opacity="0.5" />
            <circle cx="24" cy="24" r="21" fill="none" stroke="url(#logoGrad)" strokeWidth="1" opacity="0.3" />
            <rect x="32" y="20" width="2" height="8" fill={BRAND.teal} rx="1" />
            <rect x="36" y="16" width="2" height="16" fill={BRAND.azure} rx="1" />
            <rect x="40" y="22" width="2" height="4" fill={BRAND.violet} rx="1" />
          </svg>
          <div>
            <h1 style={S.brandName}>
              <span style={{fontWeight: 300}}>Cloud</span>
              <span style={S.brandPhlog}>Phlog</span>
            </h1>
            <p style={S.tagline}>Soundscape sharing for creators</p>
          </div>
        </div>

        <div style={S.statsRow}>
          <div style={S.stat}>
            <div style={S.statNum}>{soundscapes.length}</div>
            <div style={S.statLabel}>Soundscapes</div>
          </div>
          <div style={S.stat}>
            <div style={S.statNum}>{totalPlays.toLocaleString()}</div>
            <div style={S.statLabel}>Total Plays</div>
          </div>
          <div style={S.stat}>
            <div style={S.statNum}>{Math.round(totalDuration / 60)}m</div>
            <div style={S.statLabel}>Duration</div>
          </div>
        </div>
      </header>

      {/* SEARCH + FILTER + ADD */}
      <section style={S.controls}>
        <div style={S.searchWrap}>
          <svg width="20" height="20" viewBox="0 0 20 20" fill="none" style={S.searchIcon}>
            <circle cx="9" cy="9" r="6" stroke="rgba(255,255,255,0.5)" strokeWidth="2"/>
            <path d="M14 14L18 18" stroke="rgba(255,255,255,0.5)" strokeWidth="2" strokeLinecap="round"/>
          </svg>
          <input
            type="text"
            placeholder="Search soundscapes, tags, categories..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            style={S.search}
          />
        </div>

        <button onClick={() => { setShowForm(!showForm); if (editMode) resetForm(); }} style={S.addBtn}>
          {showForm ? '✕ Close' : '+ New Soundscape'}
        </button>
      </section>

      <section style={S.pillRow}>
        {['All', ...CATEGORIES].map(cat => (
          <button
            key={cat}
            onClick={() => setActiveCategory(cat)}
            style={{
              ...S.pill,
              ...(activeCategory === cat ? S.pillActive : {})
            }}
          >
            {cat}
          </button>
        ))}
      </section>

      {/* CREATE/EDIT FORM */}
      {showForm && (
        <section style={S.formSection}>
          <div style={S.formCard}>
            <h2 style={S.formTitle}>
              {editMode ? 'Edit soundscape' : 'Upload new soundscape'}
            </h2>
            <form onSubmit={editMode ? handleUpdate : handleCreate}>
              <div style={S.formGrid}>
                <div style={S.field}>
                  <label style={S.label}>Title</label>
                  <input type="text" value={formData.title} required
                    onChange={(e) => setFormData({...formData, title: e.target.value})}
                    placeholder="e.g., Forest Rain at Dawn" style={S.input} />
                </div>
                <div style={S.field}>
                  <label style={S.label}>Category</label>
                  <select value={formData.category} required
                    onChange={(e) => setFormData({...formData, category: e.target.value})} style={S.input}>
                    <option value="">Select category</option>
                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
                <div style={S.field}>
                  <label style={S.label}>Duration (seconds)</label>
                  <input type="number" value={formData.duration} required
                    onChange={(e) => setFormData({...formData, duration: e.target.value})}
                    placeholder="180" style={S.input} />
                </div>
                <div style={S.field}>
                  <label style={S.label}>Tags</label>
                  <input type="text" value={formData.tags} required
                    onChange={(e) => setFormData({...formData, tags: e.target.value})}
                    placeholder="rain, forest, ambient" style={S.input} />
                </div>
                <div style={{...S.field, gridColumn: 'span 2'}}>
                  <label style={S.label}>Audio URL (Blob Storage)</label>
                  <input type="url" value={formData.blobUrl} required
                    onChange={(e) => setFormData({...formData, blobUrl: e.target.value})}
                    placeholder="https://cloudphlogstorage.blob.core.windows.net/..." style={S.input} />
                </div>
              </div>
              <div style={S.formActions}>
                <button type="submit" style={S.submitBtn}>
                  {editMode ? 'Save changes' : 'Upload soundscape'}
                </button>
                <button type="button" onClick={resetForm} style={S.cancelBtn}>Cancel</button>
              </div>
            </form>
          </div>
        </section>
      )}

      {/* SOUNDSCAPE GRID */}
      <section style={S.grid}>
        {loading ? (
          <div style={S.loader}>
            <div style={S.spinner}></div>
            <p style={{color: 'rgba(255,255,255,0.5)', marginTop: 16}}>Loading soundscapes...</p>
          </div>
        ) : filteredSoundscapes.length === 0 ? (
          <div style={S.empty}>
            <div style={{fontSize: 64, marginBottom: 16}}>🎧</div>
            <h3 style={{color: 'rgba(255,255,255,0.8)', fontSize: 24}}>
              {searchQuery || activeCategory !== 'All' ? 'No matches found' : 'No soundscapes yet'}
            </h3>
            <p style={{color: 'rgba(255,255,255,0.4)', marginTop: 8}}>
              {searchQuery || activeCategory !== 'All' ? 'Try a different search or category' : 'Upload your first soundscape above'}
            </p>
          </div>
        ) : (
          <div style={S.cardGrid}>
            {filteredSoundscapes.map(sc => (
              <SoundscapeCard
                key={sc.id}
                sc={sc}
                isPlaying={playingId === sc.id}
                onPlay={() => handlePlay(sc)}
                onEdit={() => handleEdit(sc)}
                onDelete={() => handleDelete(sc.id)}
              />
            ))}
          </div>
        )}
      </section>

      {/* HIDDEN AUDIO PLAYER */}
      <audio ref={audioRef} onEnded={() => setPlayingId(null)} />

      {/* NOW-PLAYING BAR */}
      {playingId && (
        <NowPlayingBar
          soundscape={soundscapes.find(s => s.id === playingId)}
          onClose={() => { audioRef.current?.pause(); setPlayingId(null); }}
        />
      )}

      {/* FOOTER */}
      <footer style={S.footer}>
        <p style={{color: 'rgba(255,255,255,0.3)', fontSize: 13}}>
          CloudPhlog · COM682 Cloud Native Development · Imran Mahmud B00974566 · Ulster University 2026
        </p>
      </footer>

      {/* GLOBAL STYLES */}
      <style>{`
        * { box-sizing: border-box; margin: 0; padding: 0; }
        body { font-family: 'Outfit', -apple-system, sans-serif; background: ${BRAND.navyDeep}; color: white; -webkit-font-smoothing: antialiased; }
        @keyframes float { 0%, 100% { transform: translate(0, 0); } 50% { transform: translate(20px, -20px); } }
        @keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }
        @keyframes pulse { 0%, 100% { opacity: 0.6; } 50% { opacity: 1; } }
        @keyframes wave { 0%, 100% { transform: scaleY(0.5); } 50% { transform: scaleY(1); } }
        @keyframes fadeUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
        input:focus, select:focus { outline: none; border-color: ${BRAND.teal} !important; box-shadow: 0 0 0 3px rgba(0, 229, 160, 0.15) !important; }
        button:hover { transform: translateY(-1px); }
        button:active { transform: translateY(0); }
      `}</style>
    </div>
  );
}

// ============ SOUNDSCAPE CARD COMPONENT ============
function SoundscapeCard({ sc, isPlaying, onPlay, onEdit, onDelete }) {
  const [hover, setHover] = useState(false);

  const catColors = {
    Nature: BRAND.teal,
    Music: BRAND.violet,
    Water: BRAND.azure,
    Ambient: '#F59E0B',
  };
  const accent = catColors[sc.category] || BRAND.teal;

  const formatTime = (s) => {
    const m = Math.floor(s / 60);
    const sec = s % 60;
    return `${m}:${sec.toString().padStart(2, '0')}`;
  };

  return (
    <div
      style={{
        ...S.card,
        transform: hover ? 'translateY(-6px)' : 'translateY(0)',
        boxShadow: hover ? `0 20px 50px ${accent}30` : '0 8px 20px rgba(0,0,0,0.3)',
        borderColor: isPlaying ? accent : 'rgba(255,255,255,0.08)',
      }}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
    >
      {/* Cover art */}
      <div style={{...S.cover, background: `linear-gradient(135deg, ${accent}40 0%, ${accent}10 100%)`}}>
        <div style={S.waveform}>
          {[...Array(40)].map((_, i) => (
            <div
              key={i}
              style={{
                ...S.waveBar,
                background: accent,
                height: `${20 + Math.sin(i * 0.5) * 30 + Math.random() * 20}%`,
                animation: isPlaying ? `wave ${0.4 + Math.random() * 0.6}s ease-in-out infinite` : 'none',
                animationDelay: `${i * 0.03}s`,
              }}
            />
          ))}
        </div>
        <button onClick={onPlay} style={{...S.playBtn, background: accent}}>
          {isPlaying ? (
            <svg width="24" height="24" viewBox="0 0 24 24" fill="white"><rect x="6" y="5" width="4" height="14" rx="1"/><rect x="14" y="5" width="4" height="14" rx="1"/></svg>
          ) : (
            <svg width="24" height="24" viewBox="0 0 24 24" fill="white"><path d="M8 5v14l11-7z"/></svg>
          )}
        </button>
      </div>

      {/* Info */}
      <div style={S.cardBody}>
        <div style={{...S.catBadge, background: `${accent}20`, color: accent, borderColor: `${accent}40`}}>
          {sc.category}
        </div>
        <h3 style={S.cardTitle}>{sc.title}</h3>

        <div style={S.cardMeta}>
          <span>⏱ {formatTime(sc.duration)}</span>
          <span>▶ {(sc.playCount || 0).toLocaleString()}</span>
        </div>

        {sc.tags && sc.tags.length > 0 && (
          <div style={S.tagRow}>
            {sc.tags.slice(0, 3).map((tag, i) => (
              <span key={i} style={S.tag}>{tag}</span>
            ))}
          </div>
        )}

        <div style={S.cardActions}>
          <button onClick={onEdit} style={S.editBtn}>Edit</button>
          <button onClick={onDelete} style={S.delBtn}>Delete</button>
        </div>
      </div>
    </div>
  );
}

// ============ NOW PLAYING BAR ============
function NowPlayingBar({ soundscape, onClose }) {
  if (!soundscape) return null;
  return (
    <div style={S.nowPlaying}>
      <div style={S.npLeft}>
        <div style={S.npIcon}>
          <div style={S.npPulse}></div>
          <svg width="20" height="20" viewBox="0 0 24 24" fill="white"><path d="M8 5v14l11-7z"/></svg>
        </div>
        <div>
          <div style={{fontSize: 14, fontWeight: 600}}>{soundscape.title}</div>
          <div style={{fontSize: 12, color: 'rgba(255,255,255,0.6)'}}>{soundscape.category} · Now playing</div>
        </div>
      </div>
      <div style={S.npWaves}>
        {[...Array(20)].map((_, i) => (
          <div key={i} style={{...S.npWaveBar, animation: `wave ${0.4 + Math.random() * 0.6}s ease-in-out infinite`, animationDelay: `${i * 0.05}s`}} />
        ))}
      </div>
      <button onClick={onClose} style={S.npClose}>✕</button>
    </div>
  );
}

// ============ STYLES ============
const S = {
  app: { minHeight: '100vh', background: `radial-gradient(ellipse at top, ${BRAND.navyLight} 0%, ${BRAND.navyDeep} 50%, #000 100%)`, color: 'white', position: 'relative', overflow: 'hidden', paddingBottom: 100 },
  orb1: { position: 'fixed', top: '10%', left: '10%', width: 400, height: 400, background: `radial-gradient(circle, ${BRAND.teal}20 0%, transparent 70%)`, borderRadius: '50%', filter: 'blur(40px)', animation: 'float 20s ease-in-out infinite', pointerEvents: 'none', zIndex: 0 },
  orb2: { position: 'fixed', top: '50%', right: '5%', width: 500, height: 500, background: `radial-gradient(circle, ${BRAND.azure}20 0%, transparent 70%)`, borderRadius: '50%', filter: 'blur(50px)', animation: 'float 25s ease-in-out infinite reverse', pointerEvents: 'none', zIndex: 0 },
  orb3: { position: 'fixed', bottom: '10%', left: '40%', width: 350, height: 350, background: `radial-gradient(circle, ${BRAND.violet}20 0%, transparent 70%)`, borderRadius: '50%', filter: 'blur(40px)', animation: 'float 22s ease-in-out infinite', pointerEvents: 'none', zIndex: 0 },

  header: { position: 'relative', zIndex: 1, padding: '60px 40px 30px', maxWidth: 1400, margin: '0 auto', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 30 },
  logoRow: { display: 'flex', alignItems: 'center', gap: 16 },
  brandName: { fontSize: 36, letterSpacing: '-0.02em', lineHeight: 1 },
  brandPhlog: { fontWeight: 800, background: `linear-gradient(135deg, ${BRAND.teal}, ${BRAND.azure})`, WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' },
  tagline: { fontSize: 14, color: 'rgba(255,255,255,0.5)', marginTop: 4 },
  statsRow: { display: 'flex', gap: 32 },
  stat: { textAlign: 'right' },
  statNum: { fontFamily: 'Playfair Display, serif', fontSize: 32, fontWeight: 700, background: `linear-gradient(135deg, ${BRAND.teal}, ${BRAND.azure})`, WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' },
  statLabel: { fontSize: 11, textTransform: 'uppercase', letterSpacing: '0.1em', color: 'rgba(255,255,255,0.4)', marginTop: 2 },

  controls: { position: 'relative', zIndex: 1, maxWidth: 1400, margin: '0 auto', padding: '20px 40px', display: 'flex', gap: 16, alignItems: 'center', flexWrap: 'wrap' },
  searchWrap: { position: 'relative', flex: 1, minWidth: 280 },
  searchIcon: { position: 'absolute', left: 18, top: '50%', transform: 'translateY(-50%)', pointerEvents: 'none' },
  search: { width: '100%', padding: '14px 20px 14px 50px', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 12, color: 'white', fontSize: 15, fontFamily: 'inherit', backdropFilter: 'blur(10px)' },
  addBtn: { padding: '14px 24px', background: `linear-gradient(135deg, ${BRAND.teal}, ${BRAND.azure})`, border: 'none', borderRadius: 12, color: BRAND.navyDeep, fontSize: 15, fontWeight: 700, cursor: 'pointer', transition: 'all 0.2s', fontFamily: 'inherit', boxShadow: `0 4px 16px ${BRAND.teal}40` },

  pillRow: { position: 'relative', zIndex: 1, maxWidth: 1400, margin: '0 auto', padding: '0 40px 20px', display: 'flex', gap: 10, flexWrap: 'wrap' },
  pill: { padding: '10px 20px', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 100, color: 'rgba(255,255,255,0.7)', fontSize: 14, fontWeight: 500, cursor: 'pointer', transition: 'all 0.2s', fontFamily: 'inherit' },
  pillActive: { background: `linear-gradient(135deg, ${BRAND.teal}, ${BRAND.azure})`, borderColor: 'transparent', color: BRAND.navyDeep, fontWeight: 700 },

  formSection: { position: 'relative', zIndex: 1, maxWidth: 1400, margin: '0 auto', padding: '20px 40px', animation: 'fadeUp 0.4s ease-out' },
  formCard: { background: 'rgba(255,255,255,0.03)', backdropFilter: 'blur(20px)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 20, padding: 32 },
  formTitle: { fontSize: 24, fontWeight: 700, marginBottom: 24, fontFamily: 'Playfair Display, serif' },
  formGrid: { display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: 20 },
  field: { display: 'flex', flexDirection: 'column', gap: 8 },
  label: { fontSize: 12, fontWeight: 600, color: 'rgba(255,255,255,0.6)', letterSpacing: '0.05em', textTransform: 'uppercase' },
  input: { padding: '12px 16px', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 10, color: 'white', fontSize: 14, fontFamily: 'inherit' },
  formActions: { display: 'flex', gap: 12, marginTop: 24 },
  submitBtn: { padding: '14px 32px', background: `linear-gradient(135deg, ${BRAND.teal}, ${BRAND.azure})`, border: 'none', borderRadius: 10, color: BRAND.navyDeep, fontSize: 14, fontWeight: 700, cursor: 'pointer', fontFamily: 'inherit' },
  cancelBtn: { padding: '14px 32px', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 10, color: 'white', fontSize: 14, fontWeight: 500, cursor: 'pointer', fontFamily: 'inherit' },

  grid: { position: 'relative', zIndex: 1, maxWidth: 1400, margin: '0 auto', padding: '20px 40px' },
  cardGrid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: 24 },

  card: { background: 'rgba(255,255,255,0.03)', backdropFilter: 'blur(20px)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 16, overflow: 'hidden', transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)', animation: 'fadeUp 0.5s ease-out' },
  cover: { position: 'relative', height: 180, display: 'flex', alignItems: 'center', justifyContent: 'center', overflow: 'hidden' },
  waveform: { position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 2, padding: '0 20px' },
